import crypto from 'node:crypto';

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

interface StoredUser {
  id: string;
  email: string;
  passwordHash: string;
  role: string;
}

const b64url = (buf: Buffer): string =>
  buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export class AuthService implements IAuthService {
  private readonly users = new Map<string, StoredUser>();
  private readonly attempts = new Map<string, { count: number; lockedUntil: number }>();
  private readonly maxAttempts = 5;
  private readonly lockoutMs = 15 * 60 * 1000;
  private readonly windowMs = 60 * 1000;
  private readonly maxRequests = 20;
  private readonly rate = new Map<string, { count: number; resetAt: number }>();

  async hashPassword(password: string): Promise<string> {
    const salt = crypto.randomBytes(16);
    const derived = await new Promise<Buffer>((resolve, reject) => {
      crypto.scrypt(password, salt, 64, { N: 16384, r: 8, p: 1 }, (err, key) =>
        err ? reject(err) : resolve(key)
      );
    });
    return `scrypt$${b64url(salt)}$${b64url(derived)}`;
  }

  async verifyPassword(password: string, hash: string): Promise<boolean> {
    const parts = hash.split('$');
    if (parts.length !== 3 || parts[0] !== 'scrypt') return false;
    const salt = Buffer.from(parts[1].replace(/-/g, '+').replace(/_/g, '/'), 'base64');
    const expected = Buffer.from(parts[2].replace(/-/g, '+').replace(/_/g, '/'), 'base64');
    const derived = await new Promise<Buffer>((resolve, reject) => {
      crypto.scrypt(password, salt, expected.length, { N: 16384, r: 8, p: 1 }, (err, key) =>
        err ? reject(err) : resolve(key)
      );
    }).catch(() => Buffer.alloc(0));
    if (derived.length !== expected.length) return false;
    return crypto.timingSafeEqual(derived, expected);
  }

  async generateToken(
    payload: { id: string; email: string; role?: string },
    secret: string
  ): Promise<string> {
    if (typeof secret !== 'string' || secret.length < 32) {
      throw new Error('Secret must be at least 32 characters');
    }
    const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
    const body = b64url(
      Buffer.from(
        JSON.stringify({
          ...payload,
          iat: Math.floor(Date.now() / 1000),
          exp: Math.floor(Date.now() / 1000) + 15 * 60,
        })
      )
    );
    const data = `${header}.${body}`;
    const sig = b64url(
      crypto.createHmac('sha256', secret).update(data).digest()
    );
    return `${data}.${sig}`;
  }

  async registerUser(email: string, password: string, role = 'user'): Promise<StoredUser> {
    const normalized = email.trim().toLowerCase();
    if (!EMAIL_RE.test(normalized)) throw new Error('Invalid email');
    if (password.length < 12) throw new Error('Password too weak');
    if (this.users.has(normalized)) throw new Error('User exists');
    const user: StoredUser = {
      id: crypto.randomUUID(),
      email: normalized,
      passwordHash: await this.hashPassword(password),
      role,
    };
    this.users.set(normalized, user);
    return user;
  }

  private isRateLimited(ip: string): boolean {
    const now = Date.now();
    const entry = this.rate.get(ip);
    if (!entry || now > entry.resetAt) {
      this.rate.set(ip, { count: 1, resetAt: now + this.windowMs });
      return false;
    }
    entry.count += 1;
    return entry.count > this.maxRequests;
  }

  async handleLogin(
    request: { email?: string; password?: string; ip?: string }
  ): Promise<{ status: number; body: any }> {
    const ip = request.ip || 'unknown';
    try {
      if (this.isRateLimited(ip)) {
        return { status: 429, body: { error: 'RATE_LIMITED', message: 'Too many requests' } };
      }
      const email = typeof request.email === 'string' ? request.email.trim().toLowerCase() : '';
      const password = typeof request.password === 'string' ? request.password : '';
      if (!EMAIL_RE.test(email) || password.length === 0) {
        return { status: 400, body: { error: 'INVALID_INPUT', message: 'Invalid credentials format' } };
      }

      const now = Date.now();
      const attempt = this.attempts.get(ip);
      if (attempt && attempt.lockedUntil > now) {
        return { status: 429, body: { error: 'ACCOUNT_LOCKED', message: 'Too many failed attempts' } };
      }

      const user = this.users.get(email);
      const valid = user
        ? await this.verifyPassword(password, user.passwordHash)
        : await this.verifyPassword(password, await this.hashPassword(crypto.randomBytes(24).toString('hex')));

      if (!valid || !user) {
        const next: { count: number; lockedUntil: number } =
          attempt && now - (attempt.lockedUntil || 0) < this.windowMs * 2
            ? { count: attempt.count + 1, lockedUntil: 0 }
            : { count: 1, lockedUntil: 0 };
        if (next.count >= this.maxAttempts) {
          next.lockedUntil = now + this.lockoutMs;
          next.count = 0;
        }
        this.attempts.set(ip, next);
        return { status: 401, body: { error: 'INVALID_CREDENTIALS', message: 'Invalid email or password' } };
      }

      this.attempts.delete(ip);
      const secret = process.env.JWT_SECRET;
      if (!secret || secret.length < 32) {
        return { status: 500, body: { error: 'INTERNAL_SERVER_ERROR' } };
      }
      const token = await this.generateToken(
        { id: user.id, email: user.email, role: user.role },
        secret
      );
      return {
        status: 200,
        body: {
          data: { token, tokenType: 'Bearer', expiresIn: 900, user: { id: user.id, email: user.email, role: user.role } },
        },
      };
    } catch (err) {
      console.error(
        JSON.stringify({ level: 'error', msg: 'login_failure', code: (err as Error).name })
      );
      return { status: 500, body: { error: 'INTERNAL_SERVER_ERROR' } };
    }
  }
}

