export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export class Money {
  readonly amount: number;
  readonly currency: string;

  constructor(amount: number, currency: string) {
    if (!Number.isFinite(amount)) throw new Error('Invalid amount');
    if (!currency || currency.length !== 3) throw new Error('Invalid currency');
    this.amount = Math.round(amount * 100) / 100;
    this.currency = currency.toUpperCase();
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (other.currency !== this.currency) {
      throw new Error(`Currency mismatch: ${this.currency} vs ${other.currency}`);
    }
    return new Money(this.amount + other.amount, this.currency);
  }

  equals(other: Money): boolean {
    return this.amount === other.amount && this.currency === other.currency;
  }
}

export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

interface DomainEvent {
  type: string;
  orderId: string;
  occurredAt: Date;
}

export class Order {
  private static itemSeq = 0;
  readonly id: string;
  readonly customerId: string;
  private _status: OrderStatus = 'PENDING';
  private _items: OrderItem[] = [];
  private events: DomainEvent[] = [];

  constructor(id: string, customerId: string) {
    if (!id || !customerId) throw new Error('Order requires id and customerId');
    this.id = id;
    this.customerId = customerId;
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return this._items;
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new Error(`Cannot modify order in status ${this._status}`);
    }
    if (!productId) throw new Error('productId required');
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new Error('quantity must be a positive integer');
    }
    const existing = this._items.find(i => i.id === productId);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this._items.push({ id: productId, quantity, price });
    }
    this.raiseEvent('ITEM_ADDED', { productId, quantity });
  }

  pay(): void {
    this.assertStatus('PENDING', 'pay');
    if (this._items.length === 0) throw new Error('Cannot pay an empty order');
    this._status = 'PAID';
    this.raiseEvent('ORDER_PAID', { total: this.getTotal().amount });
  }

  ship(): void {
    this.assertStatus('PAID', 'ship');
    this._status = 'SHIPPED';
    this.raiseEvent('ORDER_SHIPPED', {});
  }

  cancel(): void {
    if (this._status === 'SHIPPED' || this._status === 'CANCELLED') {
      throw new Error(`Cannot cancel order in status ${this._status}`);
    }
    this._status = 'CANCELLED';
    this.raiseEvent('ORDER_CANCELLED', {});
  }

  getTotal(): Money {
    if (this._items.length === 0) return new Money(0, 'USD');
    return this._items
      .map(i => new Money(i.price.amount * i.quantity, i.price.currency))
      .reduce((a, b) => a.add(b));
  }

  getDomainEvents(): any[] {
    return [...this._events_snapshot(), ...this.events];
  }

  private _events_snapshot(): any[] {
    return [];
  }

  private assertStatus(expected: OrderStatus, action: string): void {
    if (this._status !== expected) {
      throw new Error(`Cannot ${action}: expected ${expected}, got ${this._status}`);
    }
  }

  private raiseEvent(type: string, payload: any): void {
    this.events.push({ type, orderId: this.id, occurredAt: new Date(), ...payload });
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

const store = new Map<string, Order>();
let seq = 0;

export const InMemoryOrderRepository: IOrderRepository = {
  async findById(id: string): Promise<Order | null> {
    const found = store.get(id);
    return found ? found : null;
  },
  async save(order: Order): Promise<void> {
    store.set(order.id, order);
  },
};

export function createOrder(customerId: string): Order {
  const id = `order-${++seq}-${Date.now()}`;
  const order = new Order(id, customerId);
  return order;
}

export async function placeAndSave(
  customerId: string,
  lines: Array<{ productId: string; quantity: number; price: Money }>
): Promise<Order> {
  const order = createOrder(customerId);
  for (const l of lines) order.addItem(l.productId, l.quantity, l.price);
  await InMemoryOrderRepository.save(order);
  return order;
}

