    this._items.push({ id: productId, quantity, price });
  }

  pay(): void {
    if (this._status !== 'PENDING') {
      throw new Error(`Cannot pay an order in ${this._status} state`);
    }
    if (this._items.length === 0) {
      throw new Error('Cannot pay an empty order');
    }
    this._status = 'PAID';
    this._events.push({
      type: 'OrderPaid',
      orderId: this.id,
      occurredAt: new Date(),
    });
  }

  ship(): void {
    if (this._status !== 'PAID') {
      throw new Error(`Cannot ship an order in ${this._status} state`);
    }
    this._status = 'SHIPPED';
    this._events.push({
      type: 'OrderShipped',
      orderId: this.id,
      occurredAt: new Date(),
    });
  }

  cancel(): void {
    if (this._status === 'SHIPPED') {
      throw new Error('Cannot cancel a shipped order');
    }
    if (this._status === 'CANCELLED') {
      throw new Error('Order is already cancelled');
    }
    this._status = 'CANCELLED';
    this._events.push({
      type: 'OrderCancelled',
      orderId: this.id,
      occurredAt: new Date(),
    });
  }

  getTotal(): Money {
    if (this._items.length === 0) {
      throw new Error('Cannot compute total of an empty order');
    }
    const first = this._items[0];
    if (!first) {
      throw new Error('Order has no items');
    }
    return this._items.reduce<Money>(
      (total, item) => total.add(item.price.multiply(item.quantity)),
      new Money(0, first.price.currency)
    );
  }

  getDomainEvents(): any[] {
    return [...this._events];
  }
}

