export interface CircuitBreakerOptions {
  failureThreshold?: number;
  resetTimeoutMs?: number;
}

export class CircuitBreaker {
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;
  private currentState: CircuitState = 'CLOSED';
  private failureCount = 0;
  private openedAt = 0;

  constructor(options: CircuitBreakerOptions = {}) {
    this.failureThreshold = options.failureThreshold ?? 5;
    this.resetTimeoutMs = options.resetTimeoutMs ?? 30000;
  }

  get state(): CircuitState {
    return this.getState();
  }

  getState(): CircuitState {
    if (this.currentState === 'OPEN') {
      if (Date.now() - this.openedAt >= this.resetTimeoutMs) {
        this.currentState = 'HALF_OPEN';
      }
    }
    return this.currentState;
  }

  recordSuccess(): void {
    this.failureCount = 0;
    this.currentState = 'CLOSED';
  }

  recordFailure(): void {
    this.failureCount++;
    if (this.currentState === 'HALF_OPEN' || this.failureCount >= this.failureThreshold) {
      this.currentState = 'OPEN';
      this.openedAt = Date.now();
    }
  }

  async execute<T>(action: () => Promise<T>): Promise<T> {
    if (this.getState() === 'OPEN') {
      throw new ApiError('Circuit breaker is OPEN; request rejected', 503);
    }
    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (err) {
      this.recordFailure();
      throw err;
    }
  }
}

export class ApiError extends Error {
  readonly statusCode: number;

  constructor(message: string, statusCode: number) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
  }
}

export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class ResilientHttpClient {
  private readonly breaker: CircuitBreaker;

  constructor(circuitBreaker?: CircuitBreaker) {
    this.breaker = circuitBreaker ?? new CircuitBreaker();
  }

  async get<T>(url: string, options: RequestOptions = {}): Promise<T> {
    const { timeoutMs = 10000, headers = {} } = options;

    return this.breaker.execute(async () => {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);
      try {
        const response = await fetch(url, {
          method: 'GET',
          headers: { Accept: 'application/json', ...headers },
          signal: controller.signal,
        });
        if (!response.ok) {
          throw new ApiError(
            `GET ${url} failed with status ${response.status}`,
            response.status
          );
        }
        const text = await response.text();
        return (text ? JSON.parse(text) : undefined) as T;
      } catch (err) {
        if (err instanceof ApiError) throw err;
        if (err instanceof Error && err.name === 'AbortError') {
          throw new ApiError(`GET ${url} timed out after ${timeoutMs}ms`, 408);
        }
        throw new ApiError(
          `GET ${url} failed: ${err instanceof Error ? err.message : String(err)}`,
          0
        );
      } finally {
        clearTimeout(timer);
      }
    });
  }
}

